/**
 * פתיחה (פעם אחת בסשן): וילון בורדו, לוגו QUEEN נחשף בזהב, קו התקדמות דק — והווילון עולה אל הכיכר.
 * אחריו: ההדר יורד, הכותרת עולה מילה-מילה, הדלתות צפות. ≤1.6s. דילוג: ביקור חוזר בסשן / הפחתת תנועה / לחיצה.
 */
import { gsap, reduced } from './core';
import { playSplit } from './split';

export function initIntro(onDone: () => void) {
  const el = document.getElementById('intro');
  const h1 = document.querySelector('[data-split="now"]');
  const after = () => {
    playSplit(h1);
    const tl = gsap.timeline();
    tl.from('.site-header', { yPercent: -100, opacity: 0, duration: 0.9, ease: 'expo.out' }, 0)
      .from('.arrival .arr-kicker', { opacity: 0, x: 30 * (document.documentElement.dir === 'rtl' ? 1 : -1), duration: 0.9, ease: 'expo.out' }, 0.15)
      .from('.arrival .arr-lead', { opacity: 0, y: 16, duration: 1, ease: 'expo.out' }, 0.5)
      .from('.arrival .door', { opacity: 0, y: 60, rotationX: 22, transformPerspective: 900, transformOrigin: '50% 100%', duration: 1.2, ease: 'expo.out', stagger: 0.1 }, 0.6)
      .from('.scroll-cue', { opacity: 0, duration: 0.8 }, 1.2);
    onDone();
  };
  let seen = false;
  try { seen = sessionStorage.getItem('queen-intro') === '1'; sessionStorage.setItem('queen-intro', '1'); } catch { /* noop */ }
  if (!el || reduced() || seen) { el?.remove(); if (!reduced()) after(); else { playSplit(h1); onDone(); } return; }

  const logo = el.querySelector('.intro-logo');
  const bar = el.querySelector('.intro-bar i');
  // הווילון עולה רק כשהפוסטר (פריים אמיתי של הסצנה) מוכן — אף פעם לא אל מסך ריק. תקרה: 3.5s
  const poster = document.getElementById('stage-poster') as HTMLImageElement | null;
  const posterReady = Promise.race([
    poster ? (poster.complete ? Promise.resolve() : poster.decode().catch(() => {})) : Promise.resolve(),
    new Promise((r) => setTimeout(r, 3500)),
  ]);
  const open = gsap.timeline({ paused: true, onComplete: () => el.remove() });
  open.to(logo, { y: -14, opacity: 0, duration: 0.35, ease: 'power2.in' }, 0)
    .to(el, { clipPath: 'inset(0 0 100% 0)', duration: 0.7, ease: 'expo.inOut' }, 0.05)
    .add(after, 0.25);
  const draw = gsap.timeline();
  // קצר (Lighthouse: Speed Index) — הלוגו נחשף ב-0.6s והווילון עולה מיד כשהפוסטר מוכן
  draw.fromTo(logo, { clipPath: 'inset(0 100% 0 0)', opacity: 1 }, { clipPath: 'inset(0 0% 0 0)', duration: 0.6, ease: 'power3.inOut' })
    .fromTo(bar, { scaleX: 0 }, { scaleX: 1, duration: 0.55, ease: 'power2.inOut' }, 0.05);
  Promise.all([posterReady, new Promise((r) => draw.eventCallback('onComplete', r))]).then(() => open.play());
  el.addEventListener('click', () => { draw.progress(1); open.play(); });
}
